import Link from "next/link";
import { currentPromo } from "@/lib/promotions";
import { db } from "@/lib/db";

/**
 * Optional slim site-wide promo bar. Server component — renders the single
 * sitewide "first month free" strip. NOT mounted here: the layout orchestrator
 * decides where to mount it (e.g. above the marketing header). Safe to drop into
 * any server layout.
 *
 * The headline price is read from the CATALOGUE, not written here.
 *
 * SCOPE (owner decision, 2026-08-11): first-month-free is a **Shared Web Hosting**
 * offer only — it is NOT granted on VPS, Business Email, or game plans (see
 * lib/promo-redemption.ts firstMonthFreeAppliesTo). So this strip advertises the
 * cheapest SHARED HOSTING plan, the one product a click here can actually get for
 * $0 the first month. Reading db.plan (VPS) here would advertise a free month the
 * checkout will never grant.
 *
 * Real incident, 2026-07-26 QA: this file hardcoded `exampleRegular = 500` under
 * a comment reading "our entry VPS regularly bills $5/mo", and the docblock
 * claimed the component was "honest by construction". So the site advertised a
 * price for a product that does not exist, on every marketing page, in the strip
 * customers see first. That is not a rounding error in a comment — it is an
 * advertised price nobody can buy.
 *
 * A claim about a price must be READ FROM the thing that sets the price. Nothing
 * in this file may be a literal.
 */
export async function PromoBar() {
  const promo = currentPromo(new Date());
  // The cheapest SHARED HOSTING plan — the product the first-month-free promo
  // actually applies to. (Not db.plan / VPS: VPS never gets the free month.)
  const cheapest = await db.hostingPlan.findFirst({
    where: { active: true },
    orderBy: { priceCents: "asc" },
    select: { priceCents: true },
  });
  // No sellable plan means there is no honest claim to make, so make none.
  if (!cheapest || cheapest.priceCents <= 0) return null;
  const exampleRegular = cheapest.priceCents;

  return (
    <div className="w-full border-b border-emerald-500/20 bg-gradient-to-r from-emerald-500/10 via-teal-500/10 to-emerald-500/10">
      <Link
        href="/web-hosting"
        className="group mx-auto flex max-w-6xl flex-wrap items-center justify-center gap-x-2.5 gap-y-1 px-4 py-2 text-center text-[13px] text-slate-200"
      >
        {/* This strip is SHARED WEB HOSTING only — the one product a click here can
            actually get for $0 the first month. The product name leads and the
            price is scoped to it ("Shared Hosting from $X"), so the figure can
            never be misread as an all-plans price (VPS/game plans bill from
            month one at their own, higher prices). */}
        <span className="rounded-full bg-emerald-500/20 px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider text-emerald-200">
          Shared Hosting
        </span>
        <span className="font-semibold text-white">{promo.label}</span>
        <span aria-hidden className="text-slate-500">·</span>
        <span className="text-slate-300">
          Shared web hosting from{" "}
          <span className="font-semibold text-white">${(exampleRegular / 100).toFixed(2)}/mo</span> — $0 today, and the price you sign up at is the price you renew at.
        </span>
        <span className="font-semibold text-emerald-300 underline-offset-2 group-hover:underline">See hosting plans →</span>
      </Link>
    </div>
  );
}
"use client";

import { useEffect } from "react";
import { SCRIPTS } from "../_pages/scripts";

/**
 * Runs a ported page's own script (nav, reveal-on-scroll, the page's widgets)
 * exactly as the design's standalone file does, after the layout has mounted
 * the Aurora runtime — the same order as the design, where aurora.built.js
 * runs before the page's JS. Also:
 *  - tags <html> with `nxm-p-<slug>-root`, the scope for the design's html/body
 *    rules (never :root:has(), which restyles the whole page on every change);
 *  - keeps the fixed nav below staging's in-flow SANDBOX banner while it is on
 *    screen, writing the nav's own `top` only when it changes.
 */
/** Same rule as lib.ts unstage(), for the page script (links it builds client-side). */
const unstageJs = (js: string) => js.replace(/(["'`(=\s])\/nxm(\/[^"'`\s)<>?#]*)?(?=["'`\s)<>?#$])/g, (m, pre: string, rest?: string) =>
  rest && /\.[a-z0-9]{2,5}$/i.test(rest) ? m : pre + (rest || "/"));

export function PageRuntime({ slug, root = false }: { slug: string; root?: boolean }) {
  useEffect(() => {
    const page = document.querySelector<HTMLElement>(`.nxm-p-${slug}`);
    if (!page) return;
    const root = document.documentElement;
    const rootCls = `nxm-p-${slug}-root`;
    root.classList.add(rootCls);

    // setTimeout: parent (layout) effects — the Aurora mount — run after child
    // effects; the page script must see Aurora already mounted. The guard sits
    // at injection so the script runs exactly once per page load, whatever
    // React does with effects.
    setTimeout(() => {
      SCRIPTS[slug]?.().then(({ PAGE_SCRIPT }) => {
        if (page.dataset.pageMounted || !page.isConnected) return;
        page.dataset.pageMounted = "1";
        const s = document.createElement("script");
        s.textContent = root ? unstageJs(PAGE_SCRIPT) : PAGE_SCRIPT;
        document.body.appendChild(s);
      });
    }, 0);

    const nav = page.querySelector<HTMLElement>(".nv");
    let raf = 0, last = -1;
    const sync = () => {
      raf = 0;
      const top = Math.round(Math.max(0, page.getBoundingClientRect().top));
      if (nav && top !== last) { nav.style.top = `${top}px`; last = top; }
    };
    const queue = () => { if (!raf) raf = requestAnimationFrame(sync); };
    sync();
    addEventListener("scroll", queue, { passive: true });
    addEventListener("resize", queue);
    return () => {
      root.classList.remove(rootCls);
      removeEventListener("scroll", queue);
      removeEventListener("resize", queue);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [slug]);
  return null;
}
"use client";

import { useEffect } from "react";
import { HOME_SCRIPT } from "./script";

/** Runs the design's own homepage script (globe, nav, wizard, game showcase,
 *  counters) once the markup is in the DOM. Injected as a real script element
 *  so it behaves exactly as it does in the design's standalone page. */
export function HomeScript() {
  useEffect(() => {
    const home = document.querySelector<HTMLElement>(".nxm-home");
    if (!home) return;
    // Page-level design rules (html/body) are scoped to this class rather than
    // :root:has(.nxm-home), which made every DOM change restyle the whole page.
    const root = document.documentElement;
    root.classList.add("nxm-home-root");
    // The design script must run exactly once per page load.
    if (!home.dataset.homeMounted) {
      home.dataset.homeMounted = "1";
      const s = document.createElement("script");
      s.textContent = HOME_SCRIPT;
      document.body.appendChild(s);
    }

    // The design's nav is fixed at the top of the viewport, but on staging the
    // SANDBOX banner sits in flow above the page. Push the nav down by however
    // much of that banner is still on screen, so it never covers the nav and
    // never leaves a gap once scrolled away. Written on the nav itself and only
    // when it changes: a custom property on .nxm-home would restyle the page.
    const nav = home.querySelector<HTMLElement>(".nv");
    let raf = 0, last = -1;
    const sync = () => {
      raf = 0;
      const top = Math.round(Math.max(0, home.getBoundingClientRect().top));
      if (nav && top !== last) { nav.style.top = `${top}px`; last = top; }
    };
    const queue = () => { if (!raf) raf = requestAnimationFrame(sync); };
    sync();
    addEventListener("scroll", queue, { passive: true });
    addEventListener("resize", queue);
    return () => {
      root.classList.remove("nxm-home-root");
      removeEventListener("scroll", queue);
      removeEventListener("resize", queue);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);
  return null;
}
