  backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  animation: promo-fadein 0.28s ease both;
  const [spotsLeft, setSpotsLeft] = useState(SPOTS_START);
  const [justDeployed, setJustDeployed] = useState(false);
  const dialogRef = useRef<HTMLDivElement>(null);
  const previouslyFocused = useRef<HTMLElement | null>(null);

  useEffect(() => {
    let alive = true;
    getPromoPopupState().then((s) => {
      if (!alive) return;
      setState(s);
      if (s.show) {
        setSecondsLeft(s.secondsLeft);
        // The modal shows only on its one still-undismissed sighting; every
        // later page load (marketing or portal, either one) gets the bar
        // instead — see PromoPopupState.mode's doc comment for why this used
        // to silently skip the portal entirely.
        if (s.mode === "modal") setOpen(true);
