    return () => {
      alive = false;
    };
  }, []);

  useEffect(() => {
    if (!open && !barVisible) return;
    const t = setInterval(() => {
      setSecondsLeft((s) => {
        if (s <= 1) {
          clearInterval(t);
          setOpen(false);
          setBarVisible(false);
          return 0;
        }
        return s - 1;
      });
    }, 1000);
    return () => clearInterval(t);
  }, [open, barVisible]);

  // "Spots left" ticker — see SPOTS_START's doc comment above for what this
  // is and isn't. Runs only while the modal itself is open (not the bar).
  useEffect(() => {
    if (!open) return;
