export async function NxmFooter() {
  const [newsletterEnabled, brandNameRaw, taglineRaw, socials] = await Promise.all([
    getSettingBool("feature_newsletter", true),
    getSetting("brand_name"),
    getSetting("brand_tagline"),
    getSocialLinks(),
  ]);
  const brandName = brandNameRaw.trim() || SETTINGS_DEFAULTS.brand_name;
  const tagline = taglineRaw.trim() || SETTINGS_DEFAULTS.brand_tagline;

  const year = new Date().getFullYear();

  return (
    <footer className="footer" id="company">
      <div className="footer-in">
        <div className="fgrid">
          <div className="fbrand">
            <Link href={NXM_ROOT ? "/" : "/nxm"} className="fbrand-mark" aria-label={`${brandName} home`}>
              <Image src="/logo.png" alt={brandName} width={157} height={26} priority={false} />
            </Link>
            <p>{tagline}</p>

            {socials.length > 0 && (
              <ul className="socials" aria-label={`${brandName} on social media`}>
                {socials.map((s) => (
                  <li key={s.key}>
                    <a href={s.href} target="_blank" rel="noopener noreferrer me" aria-label={`${brandName} on ${s.label}`} title={s.label}>
                      <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor" aria-hidden="true"><path d={s.path} /></svg>
                    </a>
                  </li>
                ))}
              </ul>
            )}

            {newsletterEnabled && <NxmNewsletterForm />}
          </div>

          <div className="fcols">
            {FOOTER_COLUMNS.map((col) => (
              <FooterColumn id={col.id} title={col.title} key={col.id}>
                <ul>
                  {col.links.map((l) => (
                    <li key={l.href}>
                      <Link href={nxmHref(l.href)}>{l.label}</Link>
                    </li>
                  ))}
                </ul>
              </FooterColumn>
            ))}
          </div>
        </div>

        <div className="fbottom">
          <span>
            &copy; {year} {brandName}. All rights reserved.
          </span>
          <NxmFooterStatus root={NXM_ROOT} />
        </div>
      </div>
    </footer>
  );

