/* Trial-sale bar (components/marketing/PromoTrialPopup) on the new site: in
   normal flow at the very top instead of sticky 72px down (that offset was
   tuned for the old site's header and made it overlap the new fixed nav,
   owner 2026-09-27). The nav already positions itself under whatever is in
   flow above the page (PageRuntime / HomeScript), and the bar scrolls away. */
461:.nxm .marketing-promo-stack .promo-bar { position: relative; top: auto; z-index: 1; }

export function HomeScript() {
  useEffect(() => {
    const home = document.querySelector<HTMLElement>(".nxm-home");
    if (!home) return;
    // Page-level design rules (html/body) are scoped to this class rather than
    // :root:has(.nxm-home), which made every DOM change restyle the whole page.
    const root = document.documentElement;
    root.classList.add("nxm-home-root");
    // The design script must run exactly once per page load.
    if (!home.dataset.homeMounted) {
      home.dataset.homeMounted = "1";
      const s = document.createElement("script");
      s.textContent = HOME_SCRIPT;
      document.body.appendChild(s);
    }

    return () => {
      root.classList.remove("nxm-home-root");
    };
  }, []);
  return null;
}
