import type { Metadata } from "next";
import { currentUser } from "@/lib/auth";
import { getLatestPost } from "@/lib/blog";
import { NxmFooter } from "./_components/NxmFooter";
import { CurrencyProvider } from "@/components/currency/CurrencyContext";
import { resolveDisplayCurrency } from "@/lib/currency-display";
import { AU_ICONS } from "./_aurora/icons";
import { reviewBadgesHtml } from "./_components/ReviewBadges";
import { preload } from "react-dom";
import { HOME_SCRIPT } from "./_home/script";
import { AFTER_MAIN_HTML, HEADER_HTML, MAIN_HTML, PRE_HEADER_HTML } from "./_home/content";
import { HomeScript } from "./_home/HomeScript";
import "./home.css";
import { nxmMetadata } from "./_seo/meta";
import { load } from "./_data/home";
import { initDisplayFx } from "./_data/lib";
import { CurrencyReload } from "./_components/CurrencyReload";
import { StableHtml } from "./_components/StableHtml";
import { unstage } from "./_data/lib";
import { NXM_BASE, categoryLabel, readLabel } from "./_data/blog-shared";

/**
 * The new homepage: the design package's own markup, CSS and script
 * (generated by tools/nxm/port_home.py — never hand-edit _home/content.ts or
 * home.css) with the owner's identity changes filled in here per request:
 * the nav button, "Log in" (signed out only) and the real-only review badges,
 * plus the real catalogue data (app/nxm/_data/home.ts): `{{nxm:key}}` slots in
 * the markup and the page data the design script reads as `__NXM`.
 */
export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return nxmMetadata("/");
}

const esc = (s: string) => s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
const jsonForScript = (v: unknown) => JSON.stringify(v).replace(/</g, "\\u003c");

/** Same contract as NxmPage: `{{nxm:key}}` slots, `:html` keys trusted
 *  server-rendered markup, everything else escaped; an unfilled slot throws,
 *  so the page never renders a hole or a stale number where live data belongs. */
function fillData(html: string, slots: Record<string, string>) {
  return html.replace(/\{\{nxm:([a-zA-Z0-9_.:-]+)\}\}/g, (_, key: string) => {
    if (!(key in slots)) throw new Error(`nxm home: no value for slot "${key}"`);
    return key.endsWith(":html") ? slots[key] : esc(slots[key]);
  });
}

const INLINE_HOME =
  "(function(){var h=document.querySelector('.nxm-home');if(!h||h.dataset.homeMounted)return;h.dataset.homeMounted='1';" +
  "document.documentElement.classList.add('nxm-home-root');})();\n" + HOME_SCRIPT.replace(/<\/script/gi, "<\\/script");

const rocket = `<span class="nxm-rk"><svg class="au-ic" viewBox="0 0 24 24" aria-hidden="true">${AU_ICONS.rocket}</svg></span>`;

/** Same "Latest guide" fix as app/nxm/_components/NxmPage.tsx — see there. */
async function latestGuideHtml(): Promise<string> {
  try {
    const post = await getLatestPost();
    if (!post) return "";
    const href = `${NXM_BASE}/blog/${encodeURIComponent(post.slug)}`;
    return `<a class="nv-post" href="${esc(href)}"><span class="nv-pk">Latest guide · ${esc(categoryLabel(post.category))}</span><b>${esc(post.title)}</b><small>${esc(readLabel(post.body))}</small><span>Read the guide →</span></a>`;
  } catch {
    return "";
  }
}

export default async function NxmHome() {
  // the globe's WebGL library starts downloading with the HTML
  preload("/nxm/three.min.js", { as: "script" });
  await initDisplayFx(); // prices in the visitor's currency, resolved before the loader formats any
  const [user, display, d] = await Promise.all([currentUser(), resolveDisplayCurrency(), load()]);

  const navCta = user
    ? `<a class="nxm-btn nxm-sm nxm-navcta" href="/dashboard"><span class="nxm-bt">Open dashboard</span><span class="nxm-arw" aria-hidden="true">→</span></a>`
    : `<a class="nxm-btn nxm-sm nxm-navcta au-hov" href="/register">${rocket}<span class="nxm-bt">Deploy a server</span></a>`;

  const [reviews, latestPost] = await Promise.all([reviewBadgesHtml(), latestGuideHtml()]);

  const login = user ? "" : `<a class="nv-login" href="/login">Log in</a>`;
  const header = HEADER_HTML.replaceAll("<!--NXM:NAVCTA-->", navCta).replaceAll("<!--NXM:LOGIN-->", login).replaceAll("<!--NXM:LATESTPOST-->", latestPost);
  const main = fillData(MAIN_HTML.replace("<!--NXM:REVIEWS-->", reviews), d.slots)
"use client";

import { useState, type HTMLAttributes } from "react";

/**
 * A ported page's server-rendered markup, pinned to its first render.
 *
 * The design pages are HTML strings the page script then brings to life
 * (typeaheads, poster rows, icons, charts). Any in-place server refresh of the
 * route — e.g. the promo popup's server action setting its visitor cookie on a
 * first visit, which makes Next re-render the page — would otherwise hand
 * React a fresh string and reset innerHTML, wiping everything the script built
 * while the page stays marked as mounted. Keeping the first string means a
 * refresh never touches this subtree (React 19 compares the
 * `{__html}` object by identity, so even an identical string would reset it); a real navigation remounts it anyway.
 */
export function StableHtml({ html, as = "div", ...rest }: { html: string; as?: "div" | "main" } & HTMLAttributes<HTMLElement>) {
  // the SAME object every render: React 19 re-sets innerHTML whenever the
  // dangerouslySetInnerHTML object changes identity, even for an equal string
  const [inner] = useState(() => ({ __html: html }));
  const Tag = as;
  // Real mismatch, not a bug to chase: on the very first render this equals
  // the server's html 1:1, but the RSC wire format re-serializes the string
  // (e.g. unicode-escaping) before the client's lazy initializer runs, so
  // React's hydration diff can flag this huge string as changed even though
  // no byte a user would notice actually differs (2026-09-27 /nxm audit).
  return <Tag {...rest} dangerouslySetInnerHTML={inner} suppressHydrationWarning />;
}
<header class=\"nv\" id=\"nav\">

  const main = fillData(MAIN_HTML.replace("<!--NXM:REVIEWS-->", reviews), d.slots)
    + `<script type="application/json" id="nxm-data">${jsonForScript(d.data)}</script>`
    + d.jsonLd.map((b) => `<script type="application/ld+json">${jsonForScript(b)}</script>`).join("");

  return (
    <>
      {/* suppressHydrationWarning: INLINE_HOME below sets data-home-mounted on
          this element synchronously, during initial HTML parsing — before
          React hydrates — as an idempotency guard against re-running the
          intro on a client remount. That's a deliberate, legitimate mismatch
          (the attribute is never part of this component's own render), not a
          bug; without this, every homepage load logged a hydration-mismatch
          console error (2026-09-27 /nxm audit). */}
      <div className="nxm-home" suppressHydrationWarning>
        <StableHtml html={unstage(PRE_HEADER_HTML + header)} />
        <StableHtml as="main" id="main" html={unstage(main)} />
        {AFTER_MAIN_HTML && <div dangerouslySetInnerHTML={{ __html: unstage(AFTER_MAIN_HTML) }} />}
        {/* The design's script runs as soon as the markup above is parsed — not
            after React hydrates the whole page — so the hero's intro plays once,
            in order, instead of the title re-animating and pieces popping in a
            second late. HomeScript still runs it on client-side navigation. */}
        <script dangerouslySetInnerHTML={{ __html: unstage(INLINE_HOME) }} />
      </div>
      <CurrencyProvider initialCurrency={display.currency} rates={display.rates}>
        <NxmFooter />
        <CurrencyReload initial={display.currency} />
      </CurrencyProvider>
      <HomeScript />
    </>
  );
}
